<?php require __DIR__.'/layout.php'; require_login(); page_top('Calculadora de Desconto'); ?>
<div class="section-title"><div><h2>Calculadora de Desconto e Soma</h2><div class="muted">Use junto da prestação de contas para conferir descontos, valores líquidos e acréscimos.</div></div></div>
<div class="grid g2">
<section class="card"><label>Valor principal (R$)</label><input id="principal" inputmode="decimal" placeholder="1.000,00"><label>Desconto (%)</label><input id="pct" type="number" min="0" max="100" step="0.01" placeholder="25"><div class="actions"><button type="button" class="light pct" data-pct="5">5%</button><button type="button" class="light pct" data-pct="10">10%</button><button type="button" class="light pct" data-pct="15">15%</button><button type="button" class="light pct" data-pct="20">20%</button><button type="button" class="light pct" data-pct="25">25%</button><button type="button" class="light pct" data-pct="30">30%</button></div><hr style="border:0;border-top:1px solid #e4e8ef;margin:18px 0"><h3>Somar outros valores</h3><div class="grid g2"><input id="extra" inputmode="decimal" placeholder="250,00"><button type="button" id="add" class="gold">+ Adicionar</button></div><div id="list" style="margin-top:10px"></div></section>
<section class="card" style="background:#0b1f3a;color:white"><div style="color:#cbd5e1;font-size:12px;font-weight:800">TOTAL FINAL</div><div id="total" style="font-size:42px;font-weight:900;margin:7px 0 20px">R$ 0,00</div><div style="display:grid;gap:10px"><div>Valor principal <b style="float:right" id="rp">R$ 0,00</b></div><div>Desconto <b style="float:right" id="rd">R$ 0,00</b></div><div>Após desconto <b style="float:right" id="rl">R$ 0,00</b></div><div>Outros valores <b style="float:right" id="re">R$ 0,00</b></div></div><div class="actions"><button type="button" id="clear" class="light">Limpar</button></div></section>
</div>
<script>(()=>{const $=s=>document.querySelector(s),ex=[];const brl=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});const pm=v=>{let s=String(v||'').trim().replace(/R\$/gi,'').replace(/\s/g,'');if(!s)return 0;if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?n:0};function calc(){const p=Math.max(0,pm($('#principal').value)),pc=Math.min(100,Math.max(0,Number($('#pct').value)||0)),d=p*pc/100,l=p-d,e=ex.reduce((a,b)=>a+b,0);$('#rp').textContent=brl.format(p);$('#rd').textContent=brl.format(d);$('#rl').textContent=brl.format(l);$('#re').textContent=brl.format(e);$('#total').textContent=brl.format(l+e)}function render(){$('#list').innerHTML='';ex.forEach((v,i)=>{const d=document.createElement('div');d.style='display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #e4e8ef';d.innerHTML='<b>'+brl.format(v)+'</b>';const b=document.createElement('button');b.type='button';b.className='danger';b.textContent='Remover';b.onclick=()=>{ex.splice(i,1);render();calc()};d.appendChild(b);$('#list').appendChild(d)})}$('#principal').oninput=calc;$('#pct').oninput=calc;document.querySelectorAll('.pct').forEach(b=>b.onclick=()=>{$('#pct').value=b.dataset.pct;calc()});$('#add').onclick=()=>{const v=pm($('#extra').value);if(v){ex.push(v);$('#extra').value='';render();calc()}};$('#clear').onclick=()=>{$('#principal').value='';$('#pct').value='';$('#extra').value='';ex.length=0;render();calc()};calc()})();</script>
<?php page_bottom(); ?>
